  const NS = "http://www.w3.org/2000/svg";
  const BASE = {
    xmlns: NS,
    width: "24",
    height: "24",
    viewBox: "0 0 24 24",
    fill: "none",
    stroke: "currentColor",
    "stroke-width": "2",
    "stroke-linecap": "round",
    "stroke-linejoin": "round"
  };

  function createIcons(options) {
    const opts = options || {};
    const attrs = opts.attrs || {};
    const root = opts.nameAttr ? document : document;
    const nodes = root.querySelectorAll("[data-lucide]");
    nodes.forEach((node) => {
      const name = node.getAttribute("data-lucide");
      const body = ICONS[name];
      if (!body) return;                       // 沒收錄的名稱維持原樣，不要炸掉版面
      const svg = document.createElementNS(NS, "svg");
      Object.keys(BASE).forEach((key) => svg.setAttribute(key, BASE[key]));
      Object.keys(attrs).forEach((key) => svg.setAttribute(key, attrs[key]));
      svg.innerHTML = body;
      // 保留原節點上的 class（app.js 會加 .icon）與 aria 設定
      if (node.className && typeof node.className === "string" && !attrs.class) {
        svg.setAttribute("class", node.className);
      }
      node.replaceWith(svg);
    });
  }

  window.lucide = { createIcons, icons: ICONS };
